function validateHttpUrl(url) {
  if (typeof url !== 'string') {
    throw new TypeError('URL должен быть строкой')
  }
  if (!/^https?:\/\//i.test(url)) {
    throw new Error('URL должен начинаться с http:// или https://')
  }
  return true
}


