// Парсинг истории диалога и получение истории из bot mediator

let URL_MEDIATOR_SERVICE = agentSettings.api?.url_mediator_service ?? 'http://localhost:8080'


function escapeHTML(text) {
    return text.replace(/[<>&"']/g, (match) => `&#${match.charCodeAt(0)};`)
}

function unescapeHTML(text) {
    return text.replace(/&#(\d+);/g, (_, code) => String.fromCharCode(code))
}


/**
 * Форматирование и деформатирование ответов для mediator.
 * formatResponse: ответ craftgpt → сообщения для пользователя (с reasoning в meta/isThinking).
 * unformatResponse: история из mediator → очищенные сообщения (убрать prefix, unescape HTML).
 */
class ResponseFormatter {
    /**
     * @param {string} thinkingPrefix - префикс для thinking-сообщений (напр. "*Мои размышления:* \n\n")
     */
    constructor(thinkingPrefix) {
        this.thinkingPrefix = thinkingPrefix || ''
    }

    /**
     * Преобразует нормализованный ответ в массив сообщений для отправки пользователю.
     * Ожидает, что reasoning уже извлечён в отдельное поле (через messageProcessor.fromModelFormat).
     * Добавляет артефакты для mediator: prefix и escapeHTML к reasoning.
     * @param {object} response - {answer, reasoning?, tool_calls?, log_id?}
     * @returns {Array<{text: string, meta: object, isMarkdown: boolean}>}
     */
    formatResponse(response) {
        const messages = []
        if (response.reasoning) {
            const text = this.thinkingPrefix + escapeHTML(response.reasoning)
            messages.push({ text, meta: { isThinking: "true" }, isMarkdown: false })
        }
        if (response.answer) {
            messages.push({ text: response.answer, meta: {}, isMarkdown: true })
        }
        return messages
    }

    /**
     * Очищает артефакты formatResponse из истории mediator.
     * isThinking сообщения: убирает prefix, unescape HTML.
     * Не объединяет, не удаляет — только очистка.
     * @param {Array} history - массив из getDialog()
     * @returns {Array} очищенная копия
     */
    unformatResponse(history) {
        return history.map(item => {
            if (item.isThinking) {
                let content = item.content
                if (this.thinkingPrefix && content.startsWith(this.thinkingPrefix)) {
                    content = content.slice(this.thinkingPrefix.length)
                }
                content = unescapeHTML(content)
                return { ...item, content }
            }
            return item
        })
    }
}

let responseFormatter = new ResponseFormatter(
    (_STANDARD_MESSAGES.THINKING_PREFIX) ?? ''
)


/**
 * Возвращает результат тулзы для отправки на LLM.
 * Для сценариев формирует JSON с scenario_dialogue и scenario_result.
 * @param {object} tool - элемент очереди
 * @returns {string}
 */
function getToolResult(tool) {
    const result = tool.result ?? TOOL_DONE_MESSAGE
    if (tool._scenarioDialogue) {
        return JSON.stringify({
            scenario_dialogue: tool._scenarioDialogue,
            scenario_result: result,
        })
    }
    return result
}


/**
 * Собирает нормализованную историю с явным полем reasoning.
 * Группирует сообщения по commitId (из meta) и тулзы по commit items.
 * Объединяет thinking + answer + tool_calls в одно сообщение.
 * @param {Array} history - очищенная история (после unformatResponse и processScenarios)
 * @param {Array} toolQueue - очередь из RedisQueue (тулзы + коммиты)
 * @returns {Array} [{role, message, reasoning?, tool_calls?, tool_call_id?}]
 */
function prepareHistoryWithReasoning(history, toolQueue) {
    if (!history) return []
    const filtered = history.filter(mes => mes.type !== 30)

    // Группируем тулзы по commit-ам
    const commitGroups = []
    if (toolQueue && toolQueue.length > 0) {
        let currentTools = []
        for (const item of toolQueue) {
            if (item.type === ITEM_TYPES.function && item.executed) {
                currentTools.push(item)
            } else if (item.type === ITEM_TYPES.commit) {
                commitGroups.push({
                    tools: currentTools,
                    commitId: item.commitId,
                    replyGptToMessageId: item.replyGptToMessageId,
                    reasoning: currentTools.find(t => t.reasoning)?.reasoning ?? null,
                    executed: !!item.executed,
                })
                currentTools = []
            }
        }
        // Тулзы без коммита (commit ещё не executed)
        if (currentTools.length > 0) {
            logger.warn(
                `No commit after tools in tools history: ${JSON.stringify(toolQueue)}`
            )
        }
    }

    // Индекс commitId → commit group
    const commitById = new Map()
    for (const group of commitGroups) {
        commitById.set(group.commitId, group)
    }

    // Собираем сообщения, привязанные к commitId
    const messagesByCommit = new Map()
    const commitIdSet = new Set()
    for (const mes of filtered) {
        const cid = mes.meta?.commitId
        if (cid) {
            if (!messagesByCommit.has(cid)) messagesByCommit.set(cid, [])
            messagesByCommit.get(cid).push(mes)
            commitIdSet.add(cid)
        }
    }

    // Хелпер: построить элемент результата для commit group
    function buildCommitItem(group) {
        const commitMsgs = messagesByCommit.get(group.commitId) || []
        const thinkingMsg = commitMsgs.find(m => m.isThinking)
        const answerMsg = commitMsgs.find(m => !m.isThinking)

        const reasoning = thinkingMsg?.content
            ?? answerMsg?.meta?.reasoning
            ?? group.reasoning

        const item = {
            role: 'assistant',
            message: answerMsg ? (answerMsg.content ?? answerMsg.message) : '',
            ...(reasoning && { reasoning }),
            ...(group.tools.length > 0 && {
                tool_calls: group.tools.map(t => ({
                    id: t.toolCallId,
                    type: 'function',
                    function: { name: t.name, arguments: JSON.stringify(t.args) }
                }))
            }),
        }

        const items = [item]
        // Для non-executed коммитов function results не включаем —
        // они придут отдельно как tool_responses
        if (group.executed) {
            for (const t of group.tools) {
                items.push({
                    role: ROLE.FUNCTION,
                    message: getToolResult(t),
                    tool_call_id: t.toolCallId,
                })
            }
        }
        return items
    }

    // Два итератора: по history и по commitGroups
    const result = []
    const insertedCommits = new Set()
    let gi = 0  // индекс в commitGroups

    // Хелпер: вставить следующие commit groups привязанные к данному якорю
    function insertGroupsForAnchor(anchorId) {
        while (gi < commitGroups.length) {
            const group = commitGroups[gi]
            if (group.replyGptToMessageId !== anchorId) break

            if (insertedCommits.has(group.commitId) || group.tools.length === 0) {
                gi++
                continue
            }

            result.push(...buildCommitItem(group))
            insertedCommits.add(group.commitId)
            gi++
        }
    }

    for (let i = 0; i < filtered.length; i++) {
        const mes = filtered[i]
        const cid = mes.meta?.commitId

        // Пропускаем сообщения привязанные к commitId — уже вставлены через insertGroupsForAnchor
        if (cid && insertedCommits.has(cid)) continue

        // Обычное thinking без commitId (без тулзов)
        if (mes.isThinking && !cid) {
            const next = filtered[i + 1]
            if (next && next.role === 'assistant' && !next.isThinking && !next.meta?.commitId) {
                result.push({
                    role: 'assistant',
                    message: next.content ?? next.message,
                    reasoning: mes.content,
                })
                i++
            } else {
                result.push({
                    role: 'assistant',
                    message: '',
                    reasoning: mes.content,
                })
            }
            continue
        }

        // Обычное сообщение (не привязанное к commitId)
        if (!cid) {
            const item = {
                role: mes.role,
                message: mes.content ?? mes.message,
                ...(mes.meta?.reasoning && { reasoning: mes.meta.reasoning }),
                ...(mes.tool_calls && { tool_calls: mes.tool_calls }),
                ...(mes.tool_call_id && { tool_call_id: mes.tool_call_id }),
            }
            result.push(item)

            // После user message — вставить commit groups
            if (mes.role === 'user') {
                insertGroupsForAnchor(mes.id)
            }
            continue
        }

        // Сообщение с commitId, но commit group ещё не вставлена — вставляем
        if (cid && !insertedCommits.has(cid)) {
            const group = commitById.get(cid)
            if (group) {
                result.push(...buildCommitItem(group))
            } else {
                // commitId есть в истории, но тулзы пропали — объединяем без tool_calls
                const commitMsgs = messagesByCommit.get(cid) || []
                const thinkingMsg = commitMsgs.find(m => m.isThinking)
                const answerMsg = commitMsgs.find(m => !m.isThinking)
                const reasoning = thinkingMsg?.content ?? answerMsg?.meta?.reasoning
                const item = {
                    role: 'assistant',
                    message: answerMsg ? (answerMsg.content ?? answerMsg.message) : '',
                    ...(reasoning && { reasoning }),
                }
                result.push(item)
            }
            insertedCommits.add(cid)
        }
    }

    // Оставшиеся commit groups — только если якорь существует в history
    for (; gi < commitGroups.length; gi++) {
        const group = commitGroups[gi]
        if (insertedCommits.has(group.commitId)) continue
        if (group.tools.length === 0) continue
        if (group.replyGptToMessageId && !filtered.some(m => m.id === group.replyGptToMessageId)) continue
        result.push(...buildCommitItem(group))
    }

    return result
}


function createMessageItem(id, type, message, role, meta) {
    const itemMeta = {
        ...(meta?.reasoning && { reasoning: meta.reasoning }),
        ...(meta?.commitId && { commitId: meta.commitId }),
        ...(meta?.debug && { debug: true }),
        ...(meta?.references && { references: true }),
    }
    return {
        id,
        type,
        content: message,
        role,
        ...(meta?.isThinking && { isThinking: true }),
        ...(Object.keys(itemMeta).length > 0 && { meta: itemMeta }),
    }
}


async function getBotMediatorDialogHistoryResponse(dialogId) {
    try {
        const config = {
            headers: {
                'Content-Type': 'application/json'
            },
            httpsAgent: AGENT
        }
        const requestUrl = new URL('/webhooks/mediator/messages', URL_MEDIATOR_SERVICE)
        requestUrl.searchParams.set('dialog_id', dialogId)
        const response = await axios.get(requestUrl.href, config)
        return response.data
    } catch (error) {
        logger.error("Ошибка при вызове API opbot-botmediator: " + error.message)
    }
}


function parseMediatorDialogHistory(clientDialogHistory) {
    if (!clientDialogHistory) return []
    return clientDialogHistory.reduce((acc, message) => {
        const isUserMessage = !!message.msg
        const source = isUserMessage ? message.msg : message.reply
        const { id: msgId, meta, message_type: type, message: { text } = {} } = source ?? {}
        if (type === 1 || type === 19 || type === 30) {
            const role = isUserMessage ? ROLE.USER : ROLE.BOT
            acc.push(createMessageItem(msgId, type, text, role, meta))
        }
        return acc
    }, [])
}


function getConversationId() {
    const slots = message?.slot_context?.filled_slots || []
    const slotConvId = slots.find(s => s.slot_id === 'conversation_id')
    if (slotConvId?.value) return slotConvId.value
    const metaConvId = message?.meta?.conversation_id
    if (metaConvId) return metaConvId
    return null
}

async function getMessagesByMetaResponse(customerId, omniUserId, conversationId) {
    try {
        const config = {
            headers: {
                'Content-Type': 'application/json'
            },
            httpsAgent: AGENT
        }
        const requestUrl = new URL('/mediator/messages_by_meta', URL_MEDIATOR_SERVICE)
        const response = await axios.post(requestUrl.href, {
            CustomerId: customerId,
            OmniUserId: omniUserId,
            MetaFilter: { conversation_id: conversationId },
            SortBy: "timestamp",
            SortOrder: "Asc",
            Limit: 10000
        }, config)
        return response.data
    } catch (error) {
        logger.error("Ошибка при вызове API opbot-botmediator: " + error.message)
    }
}

async function getDialog(dialog_id) {
    try {
        let clientDialogHistory = await getBotMediatorDialogHistoryResponse(dialog_id)
        return parseMediatorDialogHistory(clientDialogHistory)
    } catch (e) {
        logger.error(`Error getDialog: ${e.message}; ${JSON.stringify(e)}.`)
    }
}

async function getDialogsHistory(customerId, omniUserId) {
    try {
        const conversationId = getConversationId()
        if (!conversationId) return []
        const history = parseMediatorDialogHistory(
            await getMessagesByMetaResponse(customerId, omniUserId, conversationId)
        )
        return history || []
    } catch (e) {
        logger.error(`Error getDialogsHistory: ${e.message}; ${JSON.stringify(e)}.`)
        return []
    }
}


/**
 * Получить историю из ботмедиатора по conversation_id и убрать
 * с конца текущий вопрос, если он там есть.
 *
 * Ботмедиатор добавляет входящее сообщение в историю активного
 * диалога до того, как вызывает /message, поэтому возвращаемая
 * история заканчивается этим сообщением. craftgpt-у мы передаём
 * текущий вопрос отдельным параметром, и он сам добавляет его в
 * историю при логировании (craftgpt/llms/llm_agent.py — history +
 * [user_message]). Если не отрезать дубликат — модель увидит вопрос
 * два раза подряд.
 *
 * Использовать только там, где история точно пришла из ботмедиатора
 * (HISTORY_FROM_BOT_MEDIATOR=true).
 *
 * Между хвостовым вопросом и концом истории могут идти служебные
 * сообщения маршрутизации (type 30: switchredirect/redirect/ack):
 * в IDA-окружении входящий сценарий проходит через aiassist2, который
 * выбирает конкретного агента (gpt_ida_qwen), и этот маршрут остаётся
 * в истории после сообщения пользователя. Поэтому ищем последнее
 * «настоящее» (не type 30) сообщение, а не просто последний элемент.
 * Сами type 30 не трогаем — они нужны processScenarios.
 */
async function getMediatorHistoryForQuery(dialog_id, question, customerId, omniUserId) {
    const history = await getDialogsHistory(customerId, omniUserId)
    if (!history || history.length === 0) return history
    let lastIdx = history.length - 1
    while (lastIdx >= 0 && history[lastIdx].type === 30) lastIdx--
    if (lastIdx < 0) return history
    const last = history[lastIdx]
    if (last.role === ROLE.USER && last.content === question) {
        return [...history.slice(0, lastIdx), ...history.slice(lastIdx + 1)]
    }
    return history
}


/**
 * Собирает историю для LLM из mediator-истории и очереди тулзов.
 * Если toolQueue пуст — возвращает историю без tool_calls.
 * Если есть выполненные тулзы — вставляет tool_calls и function results,
 * сценарные сообщения упаковываются как content функции.
 *
 * @param {Array|null} mediatorHistory - из getDialog(): [{id, type, content, role, isThinking?, meta?}], null если история не управляется агентом
 * @param {Array} toolQueue - из RedisQueue.getQueue(): [{type, name, args, toolCallId, result, executed}] + commit items
 * @returns {Array|null} история в формате craftgpt, null если входная история null
 */
function buildLLMHistory(mediatorHistory, toolQueue) {
    if (mediatorHistory === null) return null
    if (mediatorHistory.length === 0) return []

    // 1. Очистка артефактов formatResponse — только наши сообщения
    //    (processScenarios должна быть вызвана до buildLLMHistory,
    //    чтобы сценарные сообщения от других агентов не прошли через unformatResponse)
    let history = responseFormatter.unformatResponse(mediatorHistory)

    // 2. Фильтруем служебные сообщения, не относящиеся к диалогу с LLM:
    //    debug (debugReply) и references (блок «Ссылки для информации»
    //    при SHOW_REFERENCES=true — нужен пользователю, но не в истории).
    history = history.filter(mes => !mes.meta?.debug && !mes.meta?.references)

    // 3. Собираем нормализованную историю с reasoning и tool_calls
    const tools = toolQueue || []
    const normHistory = prepareHistoryWithReasoning(history, tools)

    // 4. Преобразуем в формат конкретной модели
    return typeof messageProcessor !== 'undefined'
        ? messageProcessor.toModelFormat(normHistory)
        : normHistory
}


// --- Утилиты для работы со сценарной историей ---

/**
 * Возвращает подмассив arr начиная с первого элемента >= index, с index в начале.
 * Используется для нахождения позиций switchredirect-ов после заданного сообщения.
 * @param {number[]} arr - отсортированный массив индексов (напр. позиции type=30 в истории)
 * @param {number} index - начальная позиция
 * @returns {number[]}
 */
function getArrayFromInsertPosition(arr, index) {
    const insertIndex = arr.findIndex(el => el > index)
    if (insertIndex === -1) {
        return [index]
    }
    return [index, ...arr.slice(insertIndex)]
}


/**
 * Извлекает сообщения сценария между двумя switchredirect-ами в истории.
 * Возвращает [{ scenario_dialogue: [{actor, utterance}] }, [ids]] — диалог сценария и id сообщений для исключения.
 * @param {number[]} indices - индексы switchredirect-ов (из getArrayFromInsertPosition)
 * @param {Array} history - история диалога из getDialog()
 * @param {number} inputIndex - номер группы сценарных сообщений (смещение в indices)
 * @returns {[object, string[]] | []}
 */
function getScenarioMessages(indices, history, inputIndex) {
    const currentIndex = indices[inputIndex]

    if (currentIndex === undefined) {
        return []
    }

    const nextIndex = indices[inputIndex + 1]

    let messages
    if (nextIndex === undefined) {
        messages = history.slice(currentIndex + 1)
    } else {
        messages = history.slice(currentIndex + 1, nextIndex)
    }
    const reduced = messages
        .reduce((acc, mes) => {
            if (mes.type !== 30) {
                acc.messages.push({
                    actor: mes.role,
                    utterance: mes.content
                })
                acc.ids.push(mes.id)
            }
            return acc
        }, { messages: [], ids: [] })
    return [{ scenario_dialogue: reduced.messages }, reduced.ids]
}
// @module core/references
// @requires modules/core/globals.js
// @requires modules/core/markdown.js
// Форматирование ссылок на статьи и подсветки источников

let SHARE_ID = (agentSettings.agent_parameters ?? {}).SHARE_ID ?? null
const MAX_SOURCE_HIGHLIGHT_RANGES = 20
const SOURCE_HIGHLIGHT_CONTRACT_VERSION = '1'
const SOURCE_HIGHLIGHT_VERSION_PARAM = 'ctv'
const SOURCE_HIGHLIGHT_RANGE_PARAM = 'ctr'


function wrapInMarkdownCodeBlock(str) {
    // Экранируем только неэкранированные тройные кавычки
    const escapedStr = str.replace(/(?<!\\)```/g, '\\```')
    return `\`\`\`
${escapedStr}
\`\`\``
}


function isValidSourceHighlightRange(start, end) {
    return Number.isSafeInteger(start) &&
        Number.isSafeInteger(end) &&
        start >= 0 &&
        end > start
}


function rangesOverlapOrTouch(left, right) {
    return left.start <= right.end + 1 && right.start <= left.end + 1
}


function normalizeSourceHighlightRanges(ranges) {
    const seenRanges = new Set()
    const sourceRanges = Array.isArray(ranges) ? ranges : []
    const uniqueRanges = []

    sourceRanges.forEach((range, order) => {
        if (!range || !isValidSourceHighlightRange(range.start, range.end)) {
            return
        }

        const key = `${range.start}:${range.end}`

        if (!seenRanges.has(key)) {
            seenRanges.add(key)
            uniqueRanges.push({ ...range, order })
        }
    })

    const mergedRanges = uniqueRanges
        .sort((left, right) => left.start - right.start || left.end - right.end)
        .reduce((result, range) => {
            const lastRange = result[result.length - 1]

            if (!lastRange || !rangesOverlapOrTouch(lastRange, range)) {
                result.push(range)
                return result
            }

            result[result.length - 1] = {
                start: lastRange.start,
                end: Math.max(lastRange.end, range.end),
                order: Math.min(lastRange.order, range.order),
            }

            return result
        }, [])

    return mergedRanges
        .sort((left, right) => left.order - right.order)
        .map(({ start, end }) => ({ start, end }))
}


function capNormalizedSourceHighlightRanges(ranges) {
    return ranges.slice(0, MAX_SOURCE_HIGHLIGHT_RANGES)
}


function getSourceHighlightRangeMaps(fullContext) {
    const rangesByArticle = new Map()
    const symbolCodes = Array.isArray(fullContext?.symbol_code) ? fullContext.symbol_code : []
    const startIndexes = Array.isArray(fullContext?.start_index) ? fullContext.start_index : []
    const endIndexes = Array.isArray(fullContext?.end_index) ? fullContext.end_index : []

    symbolCodes.forEach((articleCode, idx) => {
        if (typeof articleCode !== 'string' || !articleCode) {
            return
        }

        const start = startIndexes[idx]
        const end = endIndexes[idx]

        if (!isValidSourceHighlightRange(start, end)) {
            return
        }

        const ranges = rangesByArticle.get(articleCode) || []
        ranges.push({ start, end })
        rangesByArticle.set(articleCode, ranges)
    })

    const validationRangesByArticle = new Map()

    rangesByArticle.forEach((ranges, articleCode) => {
        const normalizedRanges = normalizeSourceHighlightRanges(ranges)

        if (normalizedRanges.length) {
            validationRangesByArticle.set(articleCode, normalizedRanges)
        }
    })

    const fallbackRangesByArticle = new Map()

    validationRangesByArticle.forEach((ranges, articleCode) => {
        fallbackRangesByArticle.set(
            articleCode,
            capNormalizedSourceHighlightRanges(ranges),
        )
    })

    return {
        validationRangesByArticle,
        fallbackRangesByArticle,
    }
}


function getSourceHighlightRangesByArticle(fullContext) {
    return getSourceHighlightRangeMaps(fullContext).fallbackRangesByArticle
}


function addSourceHighlightSearchParams(url, ranges) {
    url.searchParams.delete(SOURCE_HIGHLIGHT_VERSION_PARAM)
    url.searchParams.delete(SOURCE_HIGHLIGHT_RANGE_PARAM)

    if (ranges.length === 0) {
        return
    }

    url.searchParams.set(SOURCE_HIGHLIGHT_VERSION_PARAM, SOURCE_HIGHLIGHT_CONTRACT_VERSION)
    ranges.forEach(({ start, end }) => {
        url.searchParams.append(SOURCE_HIGHLIGHT_RANGE_PARAM, `${start}:${end}`)
    })
}


function getArticleUrl(intentId, ranges = []) {
    const baseArticleUrl = SHARE_ID
        ? `${BASE_URL}/app/share/${SHARE_ID}/article/${intentId}`
        : `${BASE_URL}/app/project/${CUSTOMER_ID}/knowledge-base/article/view/${intentId}`
    const normalizedRanges = capNormalizedSourceHighlightRanges(
        normalizeSourceHighlightRanges(ranges),
    )

    if (normalizedRanges.length === 0) {
        return baseArticleUrl
    }

    const url = new URL(baseArticleUrl)
    addSourceHighlightSearchParams(url, normalizedRanges)

    return url.toString()
}


function getTitleWithUrl(intentId, title, ranges = []) {
    return `[${title}](${getArticleUrl(intentId, ranges)})`
}


function getContextSourceHighlightRange(fullContext, idx) {
    const start = fullContext?.start_index?.[idx]
    const end = fullContext?.end_index?.[idx]

    return isValidSourceHighlightRange(start, end)
        ? [{ start, end }]
        : []
}


function addUrlToContextTitle(fullContext, sourceHighlightsEnabled = false) {
    fullContext.symbol_code.forEach((intentId, idx) => {
        const title = fullContext.context[idx].title
        const ranges = sourceHighlightsEnabled
            ? getContextSourceHighlightRange(fullContext, idx)
            : []

        fullContext.context[idx].title = getTitleWithUrl(intentId, title, ranges)
    })
}


function getArticlePathPrefixes() {
    const prefixes = [
        `/app/project/${CUSTOMER_ID}/knowledge-base/article/view/`,
    ]

    if (SHARE_ID) {
        prefixes.push(`/app/share/${SHARE_ID}/article/`)
    }

    return prefixes
}


function getKnowledgeBaseArticleCodeFromUrl(destination) {
    let url
    let baseUrl

    try {
        url = new URL(destination, BASE_URL)
        baseUrl = new URL(BASE_URL)
    } catch (_) {
        return null
    }

    if (url.origin !== baseUrl.origin) {
        return null
    }

    const articlePathPrefix = getArticlePathPrefixes()
        .find(prefix => url.pathname.startsWith(prefix))

    if (!articlePathPrefix) {
        return null
    }

    const encodedArticleCode = url.pathname.slice(articlePathPrefix.length)

    try {
        const articleCode = decodeURIComponent(encodedArticleCode)

        if (
            !articleCode ||
            articleCode.includes('/') ||
            articleCode.includes('\\')
        ) {
            return null
        }

        return articleCode
    } catch (_) {
        return null
    }
}


function parseSourceHighlightRanges(url) {
    const versions = url.searchParams.getAll(SOURCE_HIGHLIGHT_VERSION_PARAM)
    const rawRanges = url.searchParams.getAll(SOURCE_HIGHLIGHT_RANGE_PARAM)

    if (
        versions.length !== 1 ||
        versions[0] !== SOURCE_HIGHLIGHT_CONTRACT_VERSION ||
        rawRanges.length === 0
    ) {
        return null
    }

    const parsedRanges = []

    for (const rawRange of rawRanges) {
        const match = /^(\d+):(\d+)$/.exec(rawRange)

        if (!match) {
            return null
        }

        const start = Number(match[1])
        const end = Number(match[2])

        if (!isValidSourceHighlightRange(start, end)) {
            return null
        }

        parsedRanges.push({ start, end })
    }

    return parsedRanges
}


function isSourceHighlightSelectionValid(url, availableRanges) {
    const selectedRanges = parseSourceHighlightRanges(url)

    if (!selectedRanges || !Array.isArray(availableRanges)) {
        return false
    }

    return selectedRanges.every(selectedRange =>
        availableRanges.some(availableRange =>
            availableRange.start <= selectedRange.start &&
            selectedRange.end <= availableRange.end
        )
    )
}


function getEnrichedArticleUrl(
    destination,
    validationRangesByArticle,
    fallbackRangesByArticle = validationRangesByArticle,
) {
    const articleCode = getKnowledgeBaseArticleCodeFromUrl(destination)

    if (!articleCode || !validationRangesByArticle.has(articleCode)) {
        return destination
    }

    try {
        const url = new URL(destination, BASE_URL)
        const availableRanges = validationRangesByArticle.get(articleCode)

        if (isSourceHighlightSelectionValid(url, availableRanges)) {
            return destination
        }

        const fallbackRanges = fallbackRangesByArticle.has(articleCode)
            ? fallbackRangesByArticle.get(articleCode)
            : availableRanges
        const normalizedFallbackRanges = capNormalizedSourceHighlightRanges(
            normalizeSourceHighlightRanges(fallbackRanges),
        )

        addSourceHighlightSearchParams(url, normalizedFallbackRanges)

        return url.toString()
    } catch (_) {
        return destination
    }
}


function enrichMarkdownArticleLinks(
    markdown,
    validationRangesByArticle,
    fallbackRangesByArticle = validationRangesByArticle,
) {
    if (
        typeof markdown !== 'string' ||
        !validationRangesByArticle ||
        typeof validationRangesByArticle.has !== 'function' ||
        typeof validationRangesByArticle.get !== 'function' ||
        validationRangesByArticle.size === 0
    ) {
        return markdown
    }

    let result = ''
    let cursor = 0

    while (cursor < markdown.length) {
        const linkStart = markdown.indexOf('[', cursor)

        if (linkStart === -1) {
            result += markdown.slice(cursor)
            break
        }

        if (linkStart > 0 && markdown[linkStart - 1] === '!') {
            result += markdown.slice(cursor, linkStart + 1)
            cursor = linkStart + 1
            continue
        }

        const titleEnd = markdown.indexOf(']', linkStart + 1)

        if (titleEnd === -1 || markdown[titleEnd + 1] !== '(') {
            result += markdown.slice(cursor, linkStart + 1)
            cursor = linkStart + 1
            continue
        }

        const urlStart = titleEnd + 2
        const urlEnd = markdown.indexOf(')', urlStart)

        if (urlEnd === -1) {
            result += markdown.slice(cursor, linkStart + 1)
            cursor = linkStart + 1
            continue
        }

        const destination = markdown.slice(urlStart, urlEnd)
        const enrichedDestination = getEnrichedArticleUrl(
            destination,
            validationRangesByArticle,
            fallbackRangesByArticle,
        )

        result += markdown.slice(cursor, urlStart)
        result += enrichedDestination
        cursor = urlEnd
    }

    return result
}


function enrichResponseArticleLinks(
    response,
    validationRangesByArticle,
    fallbackRangesByArticle = validationRangesByArticle,
) {
    if (!response || typeof response.answer !== 'string') {
        return response
    }

    const answer = enrichMarkdownArticleLinks(
        response.answer,
        validationRangesByArticle,
        fallbackRangesByArticle,
    )

    if (answer === response.answer) {
        return response
    }

    return { ...response, answer }
}


function getReferencesFromScenarios(context) {
    if (!context || context.length === 0) return ''
    const uniqueTitles = [...new Set(context.map(c => c.title).filter(Boolean))]
    if (uniqueTitles.length === 0) return ''
    return "### Ссылки для информации:" + uniqueTitles.map(t => `\n\n*  ${t}`).join('')
}


function getReferences(full_context, rangesByArticle = new Map()) {
    let references = ""
    const articles_counts = new Map()
    const articles_titles = new Map()

    // Считаем упоминания каждой статьи
    full_context.symbol_code.forEach((intent_id, idx) => {
        const prev_count = articles_counts.get(intent_id) || 0
        articles_counts.set(intent_id, prev_count + 1)
        articles_titles.set(intent_id, full_context.title[idx])
    })

    // Сортируем по убыванию числа упоминаний
    const sorted_counts = Array.from(articles_counts.entries())
        .sort((a, b) => b[1] - a[1])

    sorted_counts.forEach(([intent_id]) => {
        const url = getArticleUrl(intent_id, rangesByArticle.get(intent_id))
        references += `\n\n*  [${articles_titles.get(intent_id)}](${url})`
    })

    if (references !== "")
        references = "### Ссылки для информации:" + references
    return references
}
// @module core/context
// @requires modules/core/http.js
// Поиск контекста в базе знаний и обработка сценариев

let URL_CONTEXT_SEARCH = new URL('/search', agentSettings.api?.url_context_search).href
let URL_CONTEXT_SEARCH_SCENARIOS = new URL('/search_in_scenarios', agentSettings.api?.url_context_search).href

const _CONTEXT_SETTINGS = agentSettings.context_settings ?? {}
let {
    LAST_CONTEXT_PRICE = 0.19,
    OTHER_CONTEXT_PRICE = 3.1,
    ADD_OTHER_CONTEXT = true,
    MAX_CONTEXTS = 10,
    MAX_COMPLEX_SCENARIOS = 5,
    MAX_COMPLEX_QUESTION_EXAMPLES_LENGTH = 1000,
    CONTEXT_FROM_SCENARIOS = false,
    ADD_COMPLEX_SCENARIOS_TO_TOOLS = false,
    FILTERS = [],
    SIMPLE_INCLUDE_QUESTIONS = false,
    SIMPLE_MAX_QUESTIONS = 5,
    SIMPLE_INCLUDE_CONDITIONS = false,
    SIMPLE_TITLE_WITH_URL = true,
    RECORD_TYPE = null,
    CATALOG_IDS = null,
    TAGS = null,
} = _CONTEXT_SETTINGS


async function getContext(question, replies) {
    replies.debugReply(JSON.stringify(question))
    logger.debug(`Call CONTEXT SEARCH service`)
    let response
    try {
        response = await axios.post(
            URL_CONTEXT_SEARCH,
            {
                text: question,
                customer_id: CUSTOMER_ID,
                record_type: RECORD_TYPE,
                catalog_symbol_code: CATALOG_IDS,
                tags: TAGS,
                output_format: "json-vikhr",
                filters: FILTERS,
                size: MAX_CONTEXTS > 0 ? MAX_CONTEXTS : 100,
            }
        )

        logger.info("Response from CONTEXT SEARCH:" + JSON.stringify(response.data))
    } catch(e) {
        logger.error(`Error requesting context search: ${e}.`)
        replies.debugReply(`Error requesting context search: ${e}.`)
        _debugAxiosError(e, replies)
        throw e
    }
    const fullContext = response.data
    if (MAX_CONTEXTS > -1) {
        Object.keys(fullContext).forEach(key => {
            fullContext[key] = fullContext[key].slice(0, MAX_CONTEXTS)
        })
    }
    return fullContext
}


async function getContextFromScenarios(question, replies) {
    replies.debugReply(JSON.stringify(question))
    logger.debug(`Call CONTEXT SEARCH service (scenarios)`)
    let response
    try {
        response = await axios.post(
            URL_CONTEXT_SEARCH_SCENARIOS,
            {
                text: question,
                customer_id: CUSTOMER_ID,
                record_type: RECORD_TYPE,
                catalog_symbol_code: CATALOG_IDS,
                tags: TAGS,
                filters: FILTERS,
                size: Math.max(
                    MAX_CONTEXTS > 0 ? MAX_CONTEXTS : 100,
                    MAX_COMPLEX_SCENARIOS > 0 ? MAX_COMPLEX_SCENARIOS : 100,
                ),
            }
        )

        logger.info("Response from CONTEXT SEARCH (scenarios):" + JSON.stringify(response.data))
    } catch(e) {
        logger.error(`Error requesting context search (scen.): ${e}.`)
        replies.debugReply(`Error requesting context search (scen.): ${e}.`)
        _debugAxiosError(e, replies)
        throw e
    }
    const fullContext = response.data
    if (MAX_CONTEXTS > -1) {
        fullContext.simple = fullContext.simple.slice(0, MAX_CONTEXTS)
    }
    if (MAX_COMPLEX_SCENARIOS > -1) {
        fullContext.complex = fullContext.complex.slice(0, MAX_COMPLEX_SCENARIOS)
    }
    return fullContext
}


// --- Scenario conversion helpers ---

function isExceededLimitQuestions(ctxPartsLength, question) {
    const possibleLength = ctxPartsLength + question.length
    const maxLength = MAX_COMPLEX_QUESTION_EXAMPLES_LENGTH
    const isExceeded = possibleLength > maxLength
    if (isExceeded)
        logger.warn(`Length context exceeded(max:${MAX_COMPLEX_QUESTION_EXAMPLES_LENGTH}, possible:${possibleLength}). Question example is deleted: '${question}'`)
    return isExceeded
}


// Исключает цепочки с недопустимыми типами блоков
function isAvailableChain(excludedTypes, chain) {
    const types = chain.blocks?.map(b => b.type) || []
    return !types.some(type => excludedTypes.includes(type))
}


/**
 * Преобразует условия в читаемую строку с кастомизируемыми операторами
 */
function formatConditionsToString(posConditions, negConditions, options = {}) {
    const {
        ifPrefix = 'ЕСЛИ',
        andNotPrefix = 'И НЕ',
        notPrefix = 'НЕ',
        andOperator = 'И',
        orOperator = 'ИЛИ'
    } = options

    const formatCondition = (cond) => {
        return `${cond.slot} ${cond.condition} "${cond.value}"`
    }

    const formatAndGroup = (andGroup) => {
        if (!andGroup || andGroup.length === 0) return ''
        return andGroup.map(formatCondition).join(` ${andOperator} `)
    }

    const buildOrString = (conditions) => {
        if (!conditions || conditions.length === 0) return { str: '', compound: false }
        const groups = conditions.map(formatAndGroup).filter(Boolean)
        if (groups.length === 0) return { str: '', compound: false }
        if (groups.length === 1) return { str: groups[0], compound: false }
        return {
            str: groups.map(g => `(${g})`).join(` ${orOperator} `),
            compound: true,
        }
    }

    const pos = buildOrString(posConditions)
    const neg = buildOrString(negConditions)

    if (!pos.str && !neg.str) return ''

    const wrap = (s) => `(${s})`

    if (pos.str && neg.str) {
        const p = pos.compound ? wrap(pos.str) : pos.str
        const n = neg.compound ? wrap(neg.str) : neg.str
        return `${ifPrefix} ${p} ${andNotPrefix} ${n}`
    }
    if (pos.str) {
        return `${ifPrefix} ${pos.str}`
    }
    const n = neg.compound ? wrap(neg.str) : neg.str
    return `${ifPrefix} ${notPrefix} ${n}`
}


/** Преобразует ответ из контекстсерча в формате цепочки сценария в текст для LLM.
 * Структура цепочки: @see Chain typedef в исходных скриптах.
 */
function formatChainSimple(chain) {
    let ctxParts = []
    const blocks = chain.blocks || []

    for (const block of blocks) {
        if (!block?.type) continue

        if (block.type === "message") {
            ctxParts.push(block.text || "")
        } else if (block.type === "button") {
            ctxParts.push(`\n### ${block.text || ""}`)
        } else if (block.type === "start") {
            ctxParts.push(`\n## ${block.text || ""}`)
        } else if (block.type === "questions" && SIMPLE_INCLUDE_QUESTIONS) {
            if (Array.isArray(block.text) && block.text.length > 0) {
                const questions = block.text.slice(0, SIMPLE_MAX_QUESTIONS)
                ctxParts.push(`Примеры вопросов: ${questions.join(", ")}`)
            }
        } else if (block.type === "condition" && SIMPLE_INCLUDE_CONDITIONS) {
            const condStr = formatConditionsToString(
                block.pos_conditions, block.neg_conditions
            )
            if (condStr) {
                ctxParts.push(`**Условие:** ${condStr}`)
            }
        }
    }

    return ctxParts.join("\n")
}


function formatChainComplex(chain) {
    let ctxParts = []
    let ctxPartsLength = 0
    const blocks = chain.blocks || []
    if (!isAvailableChain(["button", "condition"], chain))
        return ""
    for (const block of blocks) {
        if (!block?.type) continue
        if (block.type === "questions") {
            block.text.forEach(question => {
                if (question && !isExceededLimitQuestions(ctxPartsLength, question)) {
                    ctxPartsLength += question.length
                    ctxParts.push(question)
                }
            })
        }
    }
    return ctxParts.join(",")
}


function extractTitleFromChain(chain, availableTypes, withUrl) {
    for (const block of (chain.blocks ?? [])) {
        if (availableTypes.includes(block.type)) {
            if (withUrl)
                return getTitleWithUrl(block.symbol_code, block.text)
            else
                return block.text
        }
    }
    return ""
}


function extractSymbolCodeFromChain(chain, availableTypes) {
    for (const block of (chain.blocks ?? [])) {
        if (availableTypes.includes(block.type)) {
            return block.symbol_code
        }
    }
    return ""
}


function convertScenariosSimple(chains) {
    let contexts = []
    let docId = 0
    for (const chain of chains) {
        if (!chain?.blocks?.length) continue
        const content = formatChainSimple(chain)
        if (!content) continue
        contexts.push({
            id: docId++,
            title: extractTitleFromChain(chain, ["start"], SIMPLE_TITLE_WITH_URL),
            content: content
        })
    }
    return contexts
}


function convertScenariosComplex(chains) {
    let contexts = []
    let docId = 0
    for (const chain of chains) {
        if (!chain?.blocks?.length) continue
        const content = formatChainComplex(chain)
        if (!content) continue
        const symbol_code = extractSymbolCodeFromChain(chain, ["complex_scenario"])
        if (!symbol_code) continue
        const title = extractTitleFromChain(chain, ["complex_scenario"], false)
        if (!title) continue
        contexts.push({
            id: docId++,
            title: title,
            content: content,
            symbol_code: symbol_code,
        })
    }
    return contexts
}


function convertScenariosToContext(chains) {
    return convertScenariosSimple(chains)
}


function convertScenariosToTools(chains) {
    return convertScenariosComplex(chains)
}
// @module core/slots
// Управление слотами: конфиг, чтение, инъекция в промпты, хранение для ответа

class SlotManager {
    /**
     * @param {object} settings - agentSettings из платформы
     * @param {object} message - объект входящего сообщения с slot_context
     */
    constructor(settings, message) {
        const cfg = settings.slots ?? {}
        this.agentSlots = cfg.agent_slots ?? {SCENARIO_RESULT: "scenario_result"}
        this.useSlots = cfg.use_slots ?? false
        this.placeholder = cfg.user_slots_placeholder ?? "## Слоты:"
        this.userSlots = cfg.user_slots ?? []
        this.replySlots = {}
        this._message = message
    }

    /**
     * Возвращает значение слота из входящего сообщения по его id.
     * @param {string} slotId
     * @returns {string|undefined}
     */
    getSlotValue(slotId) {
        return this._message.slot_context.filled_slots
            .find(slot => slot.slot_id === slotId)?.value
    }

    /**
     * Преобразует массив определений слотов в структурированный список
     * с текущими значениями из входящего сообщения.
     * Если значение содержит ";", берётся последний элемент.
     * @param {Array<{id: string, description: string}>} slots
     * @returns {Array<{slotId: string, slotDescription: string, slotValue: string|null}>}
     */
    getSlots(slots) {
        if (!slots || !Array.isArray(slots)) return []
        const filledSlots = this._message.slot_context.filled_slots
        return slots.map(slot => {
            const filledSlot = filledSlots.find(f => f.slot_id === slot.id)
            let slotValue = null
            if (filledSlot?.value) {
                const values = filledSlot.value.split(';')
                slotValue = values.length > 0 ? values[values.length - 1] : null
            }
            return { slotId: slot.id, slotDescription: slot.description, slotValue }
        })
    }

    /**
     * Устанавливает значение слота в исходящем ответе.
     * Для удаления слота передайте value = null.
     * @param {string} slotId
     * @param {string|null} value
     */
    setSlot(slotId, value) {
        this.replySlots[slotId] = value
    }

    /**
     * Объединяет переданные слоты с уже накопленными в replySlots.
     * @param {object|undefined} slots - объект {slotId: value}
     */
    mergeSlots(slots) {
        if (slots) Object.assign(this.replySlots, slots)
    }

    /**
     * Подставляет текущие значения пользовательских слотов в шаблон промпта.
     * Если useSlots=false, возвращает шаблон без изменений.
     * @param {string} template - шаблон промпта с placeholder (напр. "## Слоты:")
     * @returns {string}
     */
    injectSlotsIntoPrompt(template) {
        if (!this.useSlots) return template
        const userSlots = this.getSlots(this.userSlots)
        const slotsBlock = userSlots.length > 0
            ? userSlots.map(s =>
                `- ${s.slotId}. - ${s.slotDescription}: **${s.slotValue ?? 'не заполнено'}**`
              ).join('\n')
            : '- Нет заполненных слотов'
        return template.replace(
            this.placeholder,
            `${this.placeholder}\n${slotsBlock}`
        )
    }
}

